package agent
import("context";"fmt";"strings")
type Decision struct{LayerID string;Capability string;Escalate bool;Reason string}
func Decide(ctx context.Context,registry *LayerRegistry,category Category,capability string,allowEscalation bool)(Decision,error){if ctx==nil{return Decision{},fmt.Errorf("context is required")};if err:=ctx.Err();err!=nil{return Decision{},err};if registry==nil{return Decision{},fmt.Errorf("layer registry is required")};category=Category(strings.ToLower(strings.TrimSpace(string(category))));capability=strings.TrimSpace(capability);if category==""||len(category)>128||capability==""||len(capability)>512{return Decision{},fmt.Errorf("decision input is invalid")};layer,err:=registry.Resolve(category);if err!=nil{return Decision{},err};return Decision{LayerID:strings.TrimSpace(layer.ID),Capability:capability,Escalate:allowEscalation,Reason:"best enabled layer for category"},nil}
